svg.script:
(() => {
'use strict';

const NS = 'http://www.w3.org/2000/svg';
const svg = document.documentElement;
const defs = document.getElementById('defs');
const stage = document.getElementById('stage');
const chromeG = document.getElementById('chrome');
const meas = document.getElementById('measure');
const R = String.raw;

const C = {
  paper: '#FAF7F0', card: '#FFFDF9', rule: '#E4DDCE', rule2: '#CBC2AE',
  ink: '#1F2430', ink2: '#454D5C', ink3: '#7C8391',
  blue: '#1F4A73', blueM: '#5F81A6', blueL: '#A9BED4', blueLL: '#DCE5EE',
  gray: '#8D929A', grayD: '#666C75', grayL: '#C9CCD1',
  orange: '#DB7422', orangeD: '#B35A14', orangeL: '#EFB985', orangeLL: '#FBE6D0',
  pixLo: '#F3EDE1'
};
const SANS = "'PingFang SC','Hiragino Sans GB','Microsoft YaHei','Noto Sans CJK SC','Source Han Sans SC','WenQuanYi Micro Hei',sans-serif";
const SERIF = "'Iowan Old Style','Palatino Linotype',Palatino,'Book Antiqua',Georgia,'Times New Roman','Liberation Serif','DejaVu Serif',serif";
const MATH = "'STIX Two Text',Cambria,'Times New Roman','Liberation Serif','DejaVu Serif',serif";
const MSYM = "'STIX Two Math','Cambria Math','Latin Modern Math','DejaVu Math TeX Gyre','Noto Sans Math','Segoe UI Symbol','Apple Symbols',serif";
const MONO = "'SF Mono','JetBrains Mono','Cascadia Mono',Menlo,Consolas,'DejaVu Sans Mono','Liberation Mono',monospace";

/* ================= DDPM noise schedule: T = 1000, β linear from 1e-4 to 0.02 ================= */
const T = 1000;
const beta = new Float64Array(T + 1), alpha = new Float64Array(T + 1), abar = new Float64Array(T + 1);
abar[0] = 1; alpha[0] = 1;
for (let t = 1; t <= T; t++) {
  beta[t] = 1e-4 + (0.02 - 1e-4) * (t - 1) / (T - 1);
  alpha[t] = 1 - beta[t];
  abar[t] = abar[t - 1] * alpha[t];
}
const sA = t => Math.sqrt(abar[t]);
const sN = t => Math.sqrt(1 - abar[t]);

/* ================= small utilities ================= */
const STYLE_KEYS = { fill: 1, 'font-size': 1, 'font-weight': 1, 'font-family': 1, 'font-style': 1 };
function el(tag, attrs, parent) {
  const e = document.createElementNS(NS, tag);
  if (attrs) {
    const styled = !!attrs.class;
    for (const k in attrs) {
      const v = attrs[k];
      if (v === undefined || v === null || v === false) continue;
      if (k === 'text') e.textContent = v;
      else if (styled && STYLE_KEYS[k]) e.style.setProperty(k, k === 'font-size' && typeof v === 'number' ? v + 'px' : String(v));
      else e.setAttribute(k, v);
    }
  }
  if (parent) parent.appendChild(e);
  return e;
}
const r1 = v => Math.round(v * 10) / 10;
const r2 = v => Math.round(v * 100) / 100;
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
function mix(a, b, t) {
  t = clamp(t, 0, 1);
  const pa = parseInt(a.slice(1), 16), pb = parseInt(b.slice(1), 16);
  const ch = s => Math.round(((pa >> s) & 255) + ((((pb >> s) & 255) - ((pa >> s) & 255)) * t));
  return '#' + ((1 << 24) | (ch(16) << 16) | (ch(8) << 8) | ch(0)).toString(16).slice(1);
}
let uid = 0;
const nextId = p => p + '-' + (++uid);
const clear = g => { while (g.firstChild) g.removeChild(g.firstChild); };
const SUPD = { '-': '⁻', 0: '⁰', 1: '¹', 2: '²', 3: '³', 4: '⁴', 5: '⁵', 6: '⁶', 7: '⁷', 8: '⁸', 9: '⁹' };
function fmtSci(v, d) {
  const e = Math.floor(Math.log10(Math.abs(v)));
  return (v / Math.pow(10, e)).toFixed(d) + '×10' + String(e).split('').map(c => SUPD[c]).join('');
}
const fmtAbar = v => (v >= 0.001 ? v.toFixed(4) : fmtSci(v, 2));
const fmtBeta = t => (t >= 1 ? beta[t].toFixed(5) : '—');
const fmtSigned = v => (v < 0 ? '−' : '+') + Math.abs(v).toFixed(2);
const fmtTick = k => (k < 0 ? '−' + (-k) : String(k));

function rngFrom(seed) {
  let a = (seed >>> 0) || 1;
  const u = () => {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  let spare = null;
  const n = () => {
    if (spare !== null) { const s = spare; spare = null; return s; }
    let x, y, r;
    do { x = 2 * u() - 1; y = 2 * u() - 1; r = x * x + y * y; } while (r >= 1 || r === 0);
    const m = Math.sqrt(-2 * Math.log(r) / r);
    spare = y * m;
    return x * m;
  };
  return { u, n };
}

/* ================= text measurement ================= */
const mcache = new Map();
function measure(s, fam, size, wt, sty) {
  const key = fam + '|' + size + '|' + (wt || 400) + '|' + (sty || 'normal') + '|' + s;
  let w = mcache.get(key);
  if (w === undefined) {
    meas.setAttribute('font-family', fam);
    meas.setAttribute('font-size', size);
    meas.setAttribute('font-weight', wt || 400);
    meas.setAttribute('font-style', sty || 'normal');
    meas.textContent = s;
    w = s ? meas.getComputedTextLength() : 0;
    mcache.set(key, w);
  }
  return w;
}

/* Ink extents (ascent, descent) of a glyph, from canvas measureText; null if unavailable. */
let inkCtx;
const icache = new Map();
function ink(ch, fam, size, wt, sty) {
  const key = fam + '|' + size + '|' + wt + '|' + sty + '|' + ch;
  if (icache.has(key)) return icache.get(key);
  let r = null;
  try {
    if (inkCtx === undefined) inkCtx = document.createElementNS('http://www.w3.org/1999/xhtml', 'canvas').getContext('2d');
    if (inkCtx) {
      inkCtx.font = `${sty} ${wt} ${size}px ${fam}`;
      const m = inkCtx.measureText(ch);
      const a = m.actualBoundingBoxAscent, d = m.actualBoundingBoxDescent;
      if (typeof a === 'number' && a + d > 0.05 * size) r = [a, d];
    }
  } catch (_) { inkCtx = null; }
  icache.set(key, r);
  return r;
}

/* ================= mini TeX → SVG <text>/<tspan> typesetter ================= */
const GREEK = { alpha: 'α', beta: 'β', gamma: 'γ', delta: 'δ', epsilon: 'ϵ', varepsilon: 'ε', eta: 'η', theta: 'θ',
  lambda: 'λ', mu: 'μ', nu: 'ν', pi: 'π', rho: 'ρ', sigma: 'σ', tau: 'τ', phi: 'ϕ', psi: 'ψ', omega: 'ω',
  Sigma: 'Σ', Pi: 'Π', Delta: 'Δ', Gamma: 'Γ', Omega: 'Ω' };
const SYM = {
  cdot: ['·', 'bin', 'rm'], times: ['×', 'bin', 'rm'], pm: ['±', 'bin', 'rm'],
  sim: ['∼', 'rel', 'sym'], approx: ['≈', 'rel', 'rm'], leftarrow: ['←', 'rel', 'sym'], gets: ['←', 'rel', 'sym'],
  to: ['→', 'rel', 'sym'], rightarrow: ['→', 'rel', 'sym'], in: ['∈', 'rel', 'sym'], le: ['≤', 'rel', 'rm'],
  ge: ['≥', 'rel', 'rm'], propto: ['∝', 'rel', 'sym'], mid: ['|', 'rel', 'rm'], neq: ['≠', 'rel', 'rm'],
  nabla: ['∇', 'ord', 'sym'], ldots: ['…', 'ord', 'rm'], dots: ['…', 'ord', 'rm'], cdots: ['⋯', 'ord', 'sym'],
  infty: ['∞', 'ord', 'rm'], partial: ['∂', 'ord', 'it'], prod: ['∏', 'bigop', 'sym'], sum: ['∑', 'bigop', 'sym'],
  log: ['log', 'fn', 'rm'], exp: ['exp', 'fn', 'rm'], '|': ['‖', 'ord', 'sym'], '{': ['{', 'open', 'rm'], '}': ['}', 'close', 'rm']
};
const SPACE = { ',': 3 / 18, ':': 4 / 18, ';': 5 / 18, '!': -3 / 18, ' ': 0.25, quad: 1, qquad: 2 };
const CAL = { N: '𝒩', L: 'ℒ' }, BB = { E: '𝔼', R: 'ℝ' };
const MCOL = { blue: C.blue, gray: C.grayD, orange: C.orangeD, ink: C.ink, muted: C.ink3 };
const VF = { it: [MATH, 'italic', 400], rm: [MATH, 'normal', 400], bf: [MATH, 'normal', 700], bfit: [MATH, 'italic', 700],
  sym: [MSYM, 'normal', 400], cal: [MSYM, 'normal', 400], bb: [MSYM, 'normal', 400] };

function tokTeX(s) {
  const out = [];
  for (let i = 0; i < s.length;) {
    const c = s[i];
    if (c === '\\') {
      let j = i + 1;
      if (/[A-Za-z]/.test(s[j] || '')) {
        while (j < s.length && /[A-Za-z]/.test(s[j])) j++;
        const name = s.slice(i + 1, j);
        if (name === 'text' || name === 'c') {
          let k = j;
          while (s[k] === ' ') k++;
          const e = s.indexOf('}', k);
          out.push({ cmd: name, raw: s.slice(k + 1, e) });
          i = e + 1;
          continue;
        }
        out.push({ cmd: name });
        i = j;
      } else { out.push({ cmd: s[j] }); i = j + 1; }
    } else if (c === ' ' || c === '\n' || c === '\t') i++;
    else { const ch = String.fromCodePoint(s.codePointAt(i)); out.push({ ch }); i += ch.length; }
  }
  return out;
}
function clsOf(ch) {
  if ('+−×·±'.includes(ch)) return 'bin';
  if ('=<>≈∼≤≥→←∈'.includes(ch)) return 'rel';
  if ('(['.includes(ch)) return 'open';
  if (')]'.includes(ch)) return 'close';
  if (',;'.includes(ch)) return 'punct';
  return 'ord';
}
function parseTeX(src) {
  const tk = tokTeX(src);
  let p = 0;
  const arg = () => {
    const t = tk[p];
    if (!t) return { t: 'list', items: [] };
    if (t.ch === '{') { p++; return { t: 'list', items: list('}') }; }
    return atom();
  };
  const delim = () => {
    const t = tk[p++];
    if (!t) return '';
    if (t.ch) return t.ch === '.' ? '' : t.ch;
    if (t.cmd === '|') return '‖';
    if (t.cmd === '{') return '{';
    if (t.cmd === '}') return '}';
    return '';
  };
  function list(end) {
    const items = [];
    while (p < tk.length) {
      const t = tk[p];
      if (end === '}' && t.ch === '}') { p++; break; }
      if (end === 'right' && t.cmd === 'right') break;
      if (t.ch === '^' || t.ch === '_') {
        p++;
        const a = arg();
        let last = items.pop() || { t: 'sym', ch: '', cls: 'ord' };
        if (last.t !== 'ss') last = { t: 'ss', base: last };
        if (t.ch === '^') last.sup = a; else last.sub = a;
        items.push(last);
        continue;
      }
      const a = atom();
      if (a) items.push(a);
    }
    return items;
  }
  function atom() {
    const t = tk[p++];
    if (t.ch === '{') return { t: 'list', items: list('}') };
    if (t.cmd !== undefined) {
      const c = t.cmd;
      if (c === 'frac') { const num = arg(); return { t: 'frac', num, den: arg() }; }
      if (c === 'sqrt') return { t: 'sqrt', body: arg() };
      if (c === 'bar' || c === 'hat' || c === 'tilde') return { t: 'acc', kind: c, base: arg() };
      if (c === 'mathbf') return { t: 'font', v: 'bf', body: arg() };
      if (c === 'boldsymbol') return { t: 'font', v: 'bfit', body: arg() };
      if (c === 'mathrm') return { t: 'font', v: 'rm', body: arg() };
      if (c === 'mathcal') return { t: 'font', v: 'cal', body: arg() };
      if (c === 'mathbb') return { t: 'font', v: 'bb', body: arg() };
      if (c === 'text') return { t: 'text', str: t.raw };
      if (c === 'c') return { t: 'color', color: t.raw, body: arg() };
      if (c === 'left') {
        const l = delim();
        const body = { t: 'list', items: list('right') };
        p++;
        return { t: 'lr', l, r: delim(), body };
      }
      if (/^[bB]ig[lr]?$/.test(c)) {
        const ch = delim();
        const cls = c.endsWith('l') ? 'open' : c.endsWith('r') ? 'close' : '([{'.includes(ch) ? 'open' : ')]}'.includes(ch) ? 'close' : 'ord';
        return { t: 'delim', ch, big: c[0] === 'B' ? 2 : 1, cls };
      }
      if (SPACE[c] !== undefined) return { t: 'space', em: SPACE[c] };
      if (GREEK[c]) return { t: 'sym', ch: GREEK[c], cls: 'ord', v: /[A-Z]/.test(c[0]) ? 'rm' : undefined };
      if (SYM[c]) { const d = SYM[c]; return { t: 'sym', ch: d[0], cls: d[1], v: d[2] }; }
      return { t: 'sym', ch: c, cls: 'ord', v: 'rm' };
    }
    let ch = t.ch;
    if (ch === ':' && tk[p] && tk[p].ch === '=') { p++; return { t: 'sym', ch: ':=', cls: 'rel', v: 'rm' }; }
    if (ch === '-') ch = '−';
    return { t: 'sym', ch, cls: clsOf(ch) };
  }
  return list(null);
}

const isLat = ch => /^[A-Za-z]$/.test(ch);
const isGrk = ch => /^[α-ωϵϕ]$/.test(ch);
const isDig = ch => /^[0-9]$/.test(ch);
function defVar(ch) {
  if (isLat(ch) || isGrk(ch)) return 'it';
  if ('∇∏∑∼‖←→∈'.includes(ch)) return 'sym';
  return 'rm';
}
function metr(ch) {
  if (/^[acemnorsuvwxzαεϵικνοστυω]$/.test(ch)) return [0.47, 0.01];
  if (/^[gpqyγημρϕχ]$/.test(ch)) return [0.47, 0.23];
  if (/^[jβζξψ]$/.test(ch)) return [0.72, 0.23];
  if (/^[()[\]{}|‖]$/.test(ch)) return [0.75, 0.25];
  if (ch === '∏' || ch === '∑') return [0.72, 0];
  if (/^[=+−<>≤≥∼≈×±→←∈·]$/.test(ch) || ch === ':=') return [0.52, 0];
  if (ch === ',' || ch === ';') return [0.12, 0.2];
  return [0.7, 0];
}
function gapBetween(a, b, st) {
  if (a === 'space' || b === 'space') return 0;
  const m = st.size / 18;
  if (st.level > 0) return a === 'punct' ? 2 * m : (a === 'op' || b === 'op') ? 1.5 * m : 0;
  if (a === 'bin' || b === 'bin') return 4 * m;
  if (a === 'rel' || b === 'rel') return a === 'rel' && b === 'rel' ? 0 : 5 * m;
  if (a === 'punct') return 3 * m;
  if (a === 'op' && (b === 'ord' || b === 'inner' || b === 'op')) return 3 * m;
  if (b === 'op' && (a === 'ord' || a === 'close' || a === 'inner')) return 3 * m;
  if (a === 'inner' && (b === 'ord' || b === 'inner' || b === 'open')) return 3 * m;
  if (b === 'inner' && (a === 'ord' || a === 'close' || a === 'punct')) return 3 * m;
  return 0;
}
function mbox(n, st) {
  switch (n.t) {
    case 'list': return hcat(n.items.map(k => mbox(k, st)), st);
    case 'sym': return msym(n, st);
    case 'ss': return msupsub(n, st);
    case 'frac': return mfrac(n, st);
    case 'sqrt': return msqrt(n, st);
    case 'acc': return macc(n, st);
    case 'lr': return mlr(n, st);
    case 'delim': return mdelim(n, st);
    case 'space': return { w: n.em * st.size, h: 0, d: 0, cls: 'space', draw() {} };
    case 'text': {
      const S = st.size * 0.9, w = measure(n.str, SANS, S, 400, 'normal');
      return { w, h: 0.8 * S, d: 0.15 * S, cls: 'ord', draw(ctx, x, y) { ctx.spans.push({ x, y, t: n.str, s: S, f: SANS, st: 'normal', wt: 400, c: st.color }); } };
    }
    case 'color': return mbox(n.body, Object.assign({}, st, { color: MCOL[n.color] || n.color }));
    case 'font': return mbox(n.body, Object.assign({}, st, { v: n.v }));
  }
  return { w: 0, h: 0, d: 0, cls: 'ord', draw() {} };
}
function hcat(boxes, st) {
  for (let i = 0; i < boxes.length; i++) {
    if (boxes[i].cls !== 'bin') continue;
    let j = i - 1;
    while (j >= 0 && boxes[j].cls === 'space') j--;
    const prev = j >= 0 ? boxes[j].cls : null;
    if (!prev || /^(bin|rel|open|punct|op)$/.test(prev)) boxes[i].cls = 'ord';
  }
  const xs = [];
  let x = 0, h = 0, d = 0;
  for (let i = 0; i < boxes.length; i++) {
    if (i > 0) x += gapBetween(boxes[i - 1].cls, boxes[i].cls, st);
    xs.push(x);
    x += boxes[i].w;
    h = Math.max(h, boxes[i].h);
    d = Math.max(d, boxes[i].d);
  }
  const one = boxes.length === 1 ? boxes[0] : null;
  return { w: x, h, d, cls: one ? one.cls : 'ord', italic: one ? one.italic : false, bigop: one ? one.bigop : false,
    draw(ctx, X, Y) { for (let i = 0; i < boxes.length; i++) boxes[i].draw(ctx, X + xs[i], Y); } };
}
function msym(n, st) {
  let ch = n.ch, v = n.v || defVar(ch), cls = n.cls;
  const f0 = st.v;
  if (f0 === 'bf') { if (isLat(ch) || isDig(ch)) v = 'bf'; else if (isGrk(ch)) v = 'bfit'; }
  else if (f0 === 'bfit') { if (isLat(ch) || isGrk(ch)) v = 'bfit'; else if (isDig(ch)) v = 'bf'; }
  else if (f0 === 'rm') { if (isLat(ch) || isGrk(ch)) v = 'rm'; }
  else if (f0 === 'cal' && CAL[ch]) { ch = CAL[ch]; v = 'cal'; }
  else if (f0 === 'bb' && BB[ch]) { ch = BB[ch]; v = 'bb'; }
  let S = st.size, bigop = false, dy = 0;
  if (cls === 'fn') cls = 'op';
  if (cls === 'bigop') { bigop = true; cls = 'op'; S *= st.display && st.level === 0 ? 1.4 : 1.1; }
  const f = VF[v] || VF.rm;
  const w = measure(ch, f[0], S, f[2], f[1]);
  const m0 = metr(n.ch), k = ch.length === 1 || ch.codePointAt(0) > 0xFFFF ? ink(ch, f[0], S, f[2], f[1]) : null;
  let h = k ? k[0] : m0[0] * S, d = k ? k[1] : m0[1] * S;
  if (bigop) { dy = (h - d) / 2 - 0.25 * st.size; h -= dy; d += dy; }
  return { w, h, d, cls, italic: f[1] === 'italic', bigop,
    draw(ctx, x, y) { ctx.spans.push({ x, y: y + dy, t: ch, s: S, f: f[0], st: f[1], wt: f[2], c: st.color }); } };
}
function msupsub(n, st) {
  const base = mbox(n.base, st);
  const S = st.size;
  const sst = Object.assign({}, st, { size: S * (st.level === 0 ? 0.7 : 0.8), level: st.level + 1, display: false });
  const sup = n.sup ? mbox(n.sup, sst) : null, sub = n.sub ? mbox(n.sub, sst) : null;
  if (base.bigop && st.display && st.level === 0) {
    const w = Math.max(base.w, sup ? sup.w : 0, sub ? sub.w : 0), gap = 0.1 * S;
    return { w, h: base.h + (sup ? gap + sup.d + sup.h : 0), d: base.d + (sub ? gap + sub.h + sub.d : 0), cls: 'op',
      draw(ctx, x, y) {
        base.draw(ctx, x + (w - base.w) / 2, y);
        if (sup) sup.draw(ctx, x + (w - sup.w) / 2, y - base.h - gap - sup.d);
        if (sub) sub.draw(ctx, x + (w - sub.w) / 2, y + base.d + gap + sub.h);
      } };
  }
  let u = sup ? Math.max(0.37 * S, base.h - 0.27 * S) : 0;
  let v = sub ? Math.max(0.17 * S, base.d * 0.6 + 0.08 * S) : 0;
  if (sup && sub) {
    const gap = (u - sup.d) - (sub.h - v), need = 0.12 * S;
    if (gap < need) { u += (need - gap) / 2; v += (need - gap) / 2; }
  }
  const supdx = base.w + (base.italic ? 0.06 * S : 0.03 * S), subdx = base.w + (base.italic ? -0.01 * S : 0.02 * S);
  const w = Math.max(base.w, sup ? supdx + sup.w : 0, sub ? subdx + sub.w : 0) + 0.03 * S;
  return { w, h: Math.max(base.h, sup ? u + sup.h : 0), d: Math.max(base.d, sub ? v + sub.d : 0), cls: base.cls,
    draw(ctx, x, y) {
      base.draw(ctx, x, y);
      if (sup) sup.draw(ctx, x + supdx, y - u);
      if (sub) sub.draw(ctx, x + subdx, y + v);
    } };
}
function mfrac(n, st) {
  const S = st.size;
  const fst = st.display && st.level === 0
    ? Object.assign({}, st, { display: false })
    : Object.assign({}, st, { size: S * (st.level === 0 ? 0.8 : 0.85), level: st.level + 1, display: false });
  const num = mbox(n.num, fst), den = mbox(n.den, fst);
  const axis = 0.25 * S, th = Math.max(1, 0.05 * S), g1 = st.display ? 0.13 * S : 0.09 * S, pad = 0.1 * S;
  const w = Math.max(num.w, den.w) + 2 * pad;
  const numY = -axis - th / 2 - g1 - num.d, denY = -axis + th / 2 + g1 + den.h;
  return { w, h: -numY + num.h, d: denY + den.d, cls: 'inner',
    draw(ctx, x, y) {
      num.draw(ctx, x + (w - num.w) / 2, y + numY);
      den.draw(ctx, x + (w - den.w) / 2, y + denY);
      ctx.rects.push({ x: x + pad * 0.35, y: y - axis - th / 2, w: w - pad * 0.7, h: th, c: st.color });
    } };
}
function msqrt(n, st) {
  const S = st.size, body = mbox(n.body, st);
  const th = Math.max(1, 0.05 * S), gap = 0.1 * S;
  const top = Math.max(body.h, 0.6 * S) + gap + th / 2;
  const bot = Math.max(body.d, 0.04 * S) + 0.03 * S;
  const Ht = top + bot, sw = 0.5 * S + 0.06 * Ht;
  const w = sw + body.w + 0.1 * S;
  return { w, h: top + th / 2 + 0.03 * S, d: bot, cls: 'ord',
