/* ================= toy data: Gaussian mixtures laid along a shape ================= */
function spiralPts() {
  const pts = [];
  for (let i = 0; i <= 800; i++) {
    const u = i / 800, th = 0.55 * Math.PI + 3.1 * Math.PI * u, r = 0.28 + 1.22 * u;
    pts.push([r * Math.cos(th), r * Math.sin(th)]);
  }
  return [pts];
}
function moonsPts() {
  const a = [], b = [];
  for (let i = 0; i <= 300; i++) {
    const th = (Math.PI * i) / 300;
    a.push([Math.cos(th), Math.sin(th)]);
    b.push([1 - Math.cos(th), 0.5 - Math.sin(th)]);
  }
  return [a, b];
}
function ddpmPts() {
  const H = 1.1, h2 = H / 2, strokes = [];
  const ell = (cx, cy, rx, ry, n) => { const p = []; for (let i = 0; i <= n; i++) { const a = Math.PI / 2 - (Math.PI * i) / n; p.push([cx + rx * Math.cos(a), cy + ry * Math.sin(a)]); } return p; };
  const seg = (x1, y1, x2, y2, n) => { const p = []; for (let i = 0; i <= n; i++) p.push([x1 + ((x2 - x1) * i) / n, y1 + ((y2 - y1) * i) / n]); return p; };
  const D = x0 => strokes.push(seg(x0, -h2, x0, h2, 60).concat(ell(x0, 0, 0.62, h2, 120).slice(1)));
  const P = x0 => strokes.push(seg(x0, -h2, x0, h2, 60).concat(ell(x0, h2 / 2, 0.55, h2 / 2, 80).slice(1)));
  const M = (x0, w) => {
    const q = [[x0, -h2], [x0, h2], [x0 + w / 2, -H / 10], [x0 + w, h2], [x0 + w, -h2]];
    let s = [];
    for (let i = 0; i < 4; i++) { const sg = seg(q[i][0], q[i][1], q[i + 1][0], q[i + 1][1], 50); s = s.concat(i ? sg.slice(1) : sg); }
    strokes.push(s);
  };
  D(0); D(0.8); P(1.6); M(2.34, 0.75);
  return strokes;
}
function resample(pts, h) {
  const cum = [0];
  for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  const L = cum[cum.length - 1], n = Math.max(2, Math.round(L / h) + 1), out = [];
  let j = 0;
  for (let k = 0; k < n; k++) {
    const d = (L * k) / (n - 1);
    while (j < pts.length - 2 && cum[j + 1] < d) j++;
    const u = (d - cum[j]) / (cum[j + 1] - cum[j] || 1);
    out.push([pts[j][0] + (pts[j + 1][0] - pts[j][0]) * u, pts[j][1] + (pts[j + 1][1] - pts[j][1]) * u]);
  }
  return out;
}
const SHAPES = { spiral: { label: '螺旋', s: 0.042, gen: spiralPts }, moons: { label: '双月', s: 0.05, gen: moonsPts }, ddpm: { label: 'DDPM', s: 0.036, gen: ddpmPts } };
const SHAPE_ITEMS = Object.keys(SHAPES).map(k => ({ value: k, label: SHAPES[k].label }));
const shapeCache = {};
function getShape(name) {
  if (shapeCache[name]) return shapeCache[name];
  const def = SHAPES[name];
  let strokes = def.gen();
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (const st of strokes) for (const q of st) { x0 = Math.min(x0, q[0]); x1 = Math.max(x1, q[0]); y0 = Math.min(y0, q[1]); y1 = Math.max(y1, q[1]); }
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2, k = 3 / Math.max(x1 - x0, y1 - y0);
  strokes = strokes.map(st => resample(st.map(q => [(q[0] - cx) * k, (q[1] - cy) * k]), def.s * 1.8));
  const means = [], segs = [];
  for (const st of strokes) st.forEach((q, i) => { means.push(q[0], q[1]); if (i) segs.push(st[i - 1][0], st[i - 1][1], q[0], q[1]); });
  return (shapeCache[name] = { name, label: def.label, s: def.s, strokes, means: new Float64Array(means), K: means.length / 2, segs: new Float64Array(segs) });
}
function sampleData(shape, out, n, rng) {
  for (let i = 0; i < n; i++) {
    const k = Math.floor(rng.u() * shape.K);
    out[2 * i] = shape.means[2 * k] + shape.s * rng.n();
    out[2 * i + 1] = shape.means[2 * k + 1] + shape.s * rng.n();
  }
}
function forwardTo(x0, eps, n, t, out) {
  const a = sA(t), b = sN(t);
  for (let i = 0; i < 2 * n; i++) out[i] = a * x0[i] + b * eps[i];
}

/* Analytic optimal denoiser for q(x0) = (1/K) Σ N(m_k, s²I):
   p_t = (1/K) Σ N(√ᾱ_t m_k, v_t I) with v_t = ᾱ_t s² + 1 − ᾱ_t, and ε̂ = −√(1−ᾱ_t) ∇log p_t. */
let amBuf = new Float64Array(512), d2Buf = new Float64Array(256);
function epsHat(shape, xs, n, t, out) {
  const K = shape.K, Mn = shape.means, ab = abar[t];
  const a = Math.sqrt(ab), sq = Math.sqrt(1 - ab), v = ab * shape.s * shape.s + (1 - ab), inv2v = 0.5 / v;
  if (amBuf.length < 2 * K) { amBuf = new Float64Array(2 * K); d2Buf = new Float64Array(K); }
  const am = amBuf, d2 = d2Buf;
  for (let k = 0; k < 2 * K; k++) am[k] = a * Mn[k];
  for (let i = 0; i < n; i++) {
    const x = xs[2 * i], y = xs[2 * i + 1];
    let dmin = Infinity;
    for (let k = 0; k < K; k++) {
      const dx = x - am[2 * k], dy = y - am[2 * k + 1], q = dx * dx + dy * dy;
      d2[k] = q;
      if (q < dmin) dmin = q;
    }
    let sw = 0, mx = 0, my = 0;
    for (let k = 0; k < K; k++) {
      const e = (d2[k] - dmin) * inv2v;
      if (e > 36) continue;
      const wk = Math.exp(-e);
      sw += wk; mx += wk * am[2 * k]; my += wk * am[2 * k + 1];
    }
    mx /= sw; my /= sw;
    const gx = (mx - x) / v, gy = (my - y) / v;
    out[2 * i] = -sq * gx;
    out[2 * i + 1] = -sq * gy;
  }
}
/* One iteration of Algorithm 2 (σ_t² = β_t; z = 0 when t = 1), with ε̂ standing in for ε_θ. */
function alg2Step(shape, xs, n, t, rng, eh) {
  epsHat(shape, xs, n, t, eh);
  const c1 = 1 / Math.sqrt(alpha[t]), c2 = (1 - alpha[t]) / Math.sqrt(1 - abar[t]), sig = Math.sqrt(beta[t]);
  for (let i = 0; i < 2 * n; i++) {
    const z = t > 1 ? rng.n() : 0;
    xs[i] = c1 * (xs[i] - c2 * eh[i]) + sig * z;
  }
}
function meanDist(shape, xs, n) {
  const sg = shape.segs, ns = sg.length / 4;
  let tot = 0;
  for (let i = 0; i < n; i++) {
    const px = xs[2 * i], py = xs[2 * i + 1];
    let best = Infinity;
    for (let k = 0; k < ns; k++) {
      const ax = sg[4 * k], ay = sg[4 * k + 1], dx = sg[4 * k + 2] - ax, dy = sg[4 * k + 3] - ay;
      let u = ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy);
      u = u < 0 ? 0 : u > 1 ? 1 : u;
      const ex = ax + u * dx - px, ey = ay + u * dy - py, q = ex * ex + ey * ey;
      if (q < best) best = q;
    }
    tot += Math.sqrt(best);
  }
  return tot / n;
}
function cloudStats(xs, n) {
  let mx = 0, my = 0;
  for (let i = 0; i < n; i++) { mx += xs[2 * i]; my += xs[2 * i + 1]; }
  mx /= n; my /= n;
  let vx = 0, vy = 0;
  for (let i = 0; i < n; i++) { vx += (xs[2 * i] - mx) ** 2; vy += (xs[2 * i + 1] - my) ** 2; }
  return { mx, my, sx: Math.sqrt(vx / (n - 1)), sy: Math.sqrt(vy / (n - 1)) };
}
const stepsPerFrame = t => (t > 600 ? 8 : t > 250 ? 5 : 2);

const state = { t: 250, shape: 'spiral', seed: 1 };
const listeners = [];
function setShape(name) { if (state.shape === name) return; state.shape = name; listeners.forEach(f => f('shape')); }
function reseed() { state.seed++; listeners.forEach(f => f('seed')); }

/* ================= slides ================= */
const slides = [];
function addSlide(build, meta) {
